  allenati: 'M13 2L4 14h7l-1 8 9-12h-7z',
  sfide: 'M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0zM7 6H4a3 3 0 0 0 3 4M17 6h3a3 3 0 0 1-3 4',
  coach: 'M4 5h16v11H9l-5 4z',
